import { Box, Divider, FieldSet, FillPreview, Input } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext, useRef, useState } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../ricos-context/index.js';
import { canTransformToHex } from './../../ricos-styles/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
} from './../../_shared/color-manager-utils.js';
import { resolveDocumentColorToCss } from './../../_shared/theme-color-token.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { NewColorPicker } from './../../ui-components/color-picker/new-color-picker/index.js';
import {
  ColorWithOpacityInput,
  NumberInputWithLabel,
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { isCellOuterEdge } from '../borders/edge-detection.js';
import { getDisplayedBorderOnSide, resolveCellBordersPm } from '../borders/resolve-cell-borders.js';
import {
  TABLE_COLOR_PICKER,
  resolveDefaultBorderColor,
  resolveDisplayedBorderColor,
} from '../consts.js';
import {
  TABLE_BORDER_COLOR_INPUT,
  TABLE_BORDER_COLOR_PICKER,
  TABLE_BORDER_MODAL,
  TABLE_BORDER_WIDTH_INPUT,
} from '../data-hooks.js';
import { TableQuery } from '../tiptap/table-query.js';
import { isRicosCellSelection } from '../tiptap/utilities/is-selection-type.js';
import { BorderScopeSelector } from '../toolbar/modals/border-scope-selector.js';
import type { BordersType } from '../types.js';

type BorderSide = 'top' | 'right' | 'bottom' | 'left';
type ResolvedScopedBorder = { color: string; width: number };

const ALL_SIDES: readonly BorderSide[] = ['top', 'right', 'bottom', 'left'];

const getSidesForScope = (scope: BordersType): readonly BorderSide[] => {
  switch (scope) {
    case 'borders':
    case 'outsideBorders':
    case 'inner':
      return ALL_SIDES;
    case 'innerHorizontal':
      return ['top', 'bottom'];
    case 'innerVertical':
      return ['left', 'right'];
    case 'top':
    case 'right':
    case 'bottom':
    case 'left':
      return [scope];
    default:
      return [];
  }
};

const DEFAULT_BORDER_WIDTH = 1;

export type BorderModalProps = {
  nodeId: string;
  referenceElement: HTMLElement | undefined;
  color: string | undefined;
  onColorPreview?: (color: string | undefined) => void;
  onColorPreviewEnd?: () => void;
  onColorCommit?: (color: string | undefined) => void;
  borderWidth?: number;
  onBorderWidthPreview?: (width: number) => void;
  onBorderWidthCommit?: (finalValue: number, originalValue: number) => void;
  borderScope?: BordersType;
  onBorderScopeChange?: (scope: BordersType) => void;
  canInnerHorizontal?: boolean;
  canInnerVertical?: boolean;
};

export const BorderModal: FC<BorderModalProps> = ({
  nodeId,
  referenceElement,
  color: _color,
  onColorPreview,
  onColorPreviewEnd,
  onColorCommit,
  borderWidth: _borderWidth = 1,
  onBorderWidthPreview,
  onBorderWidthCommit,
  borderScope = 'borders',
  onBorderScopeChange,
  canInnerHorizontal = false,
  canInnerVertical = false,
}) => {
  const { t, isMobile, colorManager, theme } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const zIndexService = useContext(ZIndexContext);
  const { adapter } = useContext(EditorContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const defaultBorderColor = resolveDefaultBorderColor(
    adapter.tiptapEditor.view.dom as HTMLElement
  );

  const logBi = useBiNext({
    modalId: TABLE_COLOR_PICKER,
    pluginId: 'table',
    nodeId,
  });

  const { pmNodeAttrs } = useNodeAttrs(nodeId, 'TABLE_CELL');

  const [localBorderScope, setLocalBorderScope] = useState<BordersType>(borderScope);
  const colorPickerRef = useRef<HTMLDivElement>(null);

  // This shows what's SET on this cell, not the resolved/visible value from canonical remapping
  const getCellBorderColor = (side: 'top' | 'right' | 'bottom' | 'left'): string | undefined => {
    if (!pmNodeAttrs) {
      return undefined;
    }
    return pmNodeAttrs.borderColors?.[side];
  };

  const getCellBorderWidth = (side: 'top' | 'right' | 'bottom' | 'left'): number => {
    if (!pmNodeAttrs) {
      return DEFAULT_BORDER_WIDTH;
    }
    return pmNodeAttrs.borderWidths?.[side] ?? DEFAULT_BORDER_WIDTH;
  };

  const getScopedResolvedBorders = (): ResolvedScopedBorder[] | null => {
    const { selection } = adapter.tiptapEditor.state;
    if (!isRicosCellSelection(selection)) {
      return null;
    }
    const table = TableQuery.of(selection);
    if (!table) {
      return null;
    }

    const tableNode = table.getNode();
    const tableStart = table.getStartPos();
    const tableWidth = table.getWidth();
    const tableHeight = table.getHeight();
    const cellSpacing = (tableNode.attrs.tableData?.cellSpacing as number | undefined) ?? 0;
    const resolvedBorders = resolveCellBordersPm(tableNode, {
      drawDefaultGrid: true,
      cellSpacing,
    });

    const selectedCellIds = new Set<string>();
    selection.forEachCell(node => {
      if (node.attrs.id) {
        selectedCellIds.add(node.attrs.id);
      }
    });

    const tableMap = table.getMap();
    const isCellSelected = (row: number, col: number) => {
      if (row < 0 || row >= tableHeight || col < 0 || col >= tableWidth) {
        return false;
      }
      const cellPos = tableMap[row * tableWidth + col];
      const cell = typeof cellPos === 'number' ? tableNode.nodeAt(cellPos) : null;
      return cell ? selectedCellIds.has(cell.attrs.id) : false;
    };

    const scopedBorders: ResolvedScopedBorder[] = [];
    const addBorder = (
      node: ProseMirrorNode,
      cell: { row: number; col: number; rowspan: number; colspan: number },
      side: BorderSide
    ) => {
      const border = getDisplayedBorderOnSide(
        resolvedBorders,
        tableNode,
        node.attrs.id,
        cell,
        side
      );
      scopedBorders.push({
        color: resolveDisplayedBorderColor(border?.color, defaultBorderColor),
        width: border?.width ?? DEFAULT_BORDER_WIDTH,
      });
    };

    selection.forEachCell((node, pos) => {
      const cell = table.map.findCell(pos - tableStart);
      const sidesForBorders = (): BorderSide[] => {
        switch (localBorderScope) {
          case 'borders':
            return [...ALL_SIDES];
          case 'outsideBorders':
            return ALL_SIDES.filter(side =>
              isCellOuterEdge(cell, side, tableWidth, tableHeight, isCellSelected)
            );
          case 'top':
          case 'right':
          case 'bottom':
          case 'left':
            return isCellOuterEdge(cell, localBorderScope, tableWidth, tableHeight, isCellSelected)
              ? [localBorderScope]
              : [];
          case 'inner': {
            const sides: BorderSide[] = [];
            if (cell.row > 0 && isCellSelected(cell.row - 1, cell.col)) {
              sides.push('top');
            }
            if (cell.col > 0 && isCellSelected(cell.row, cell.col - 1)) {
              sides.push('left');
            }
            return sides;
          }
          case 'innerHorizontal':
            return cell.row > 0 && isCellSelected(cell.row - 1, cell.col) ? ['top'] : [];
          case 'innerVertical':
            return cell.col > 0 && isCellSelected(cell.row, cell.col - 1) ? ['left'] : [];
          default:
            return [];
        }
      };

      for (const side of sidesForBorders()) {
        addBorder(node, cell, side);
      }
    });

    return scopedBorders;
  };

  const getCurrentWidth = (resolvedBorders: ResolvedScopedBorder[] | null): number | undefined => {
    const allWidths =
      resolvedBorders?.map(({ width }) => width) ??
      (pmNodeAttrs ? getSidesForScope(localBorderScope).map(getCellBorderWidth) : []);

    if (allWidths.length === 0) {
      return DEFAULT_BORDER_WIDTH;
    }
    const firstWidth = allWidths[0];
    return allWidths.every(w => w === firstWidth) ? firstWidth : undefined;
  };

  const getAllCurrentColors = (resolvedBorders: ResolvedScopedBorder[] | null): string[] => {
    if (resolvedBorders) {
      return [...new Set(resolvedBorders.map(({ color }) => color))];
    }
    if (!pmNodeAttrs) {
      return [];
    }
    const sides = getSidesForScope(localBorderScope);
    return [
      ...new Set(
        sides.map(side => resolveDisplayedBorderColor(getCellBorderColor(side), defaultBorderColor))
      ),
    ];
  };

  const resolvedBorders = getScopedResolvedBorders();
  const currentWidth = getCurrentWidth(resolvedBorders);
  const allCurrentColors = getAllCurrentColors(resolvedBorders);
  const currentColor = allCurrentColors[0] ?? defaultBorderColor;
  const isMixedColor = allCurrentColors.length > 1;

  const themeColors = resolveThemeColorsPalette(theme);
  const customColors = useResolvedCustomColors(colorManager);

  const containerEl = usePanelContainerElement();
  const displayedCurrentColor = resolveDocumentColorToCss(currentColor) ?? currentColor;
  const displayedAllCurrentColors = allCurrentColors
    .map(color => resolveDocumentColorToCss(color) ?? color)
    .filter((color): color is string => typeof color === 'string');

  const closeModal = () => {
    modalService.closeModal(TABLE_COLOR_PICKER);
  };

  const handleBorderWidthPreview = (width: number | undefined) => {
    if (width === undefined) {
      return;
    }
    onBorderWidthPreview?.(width);
  };

  const handleBorderWidthCommit = (finalValue: number, originalValue: number) => {
    onBorderWidthCommit?.(finalValue, originalValue);
  };

  const handleColorPreview = (color: string | undefined) => {
    onColorPreview?.(color);
  };

  const handleColorCommit = (color: string | undefined) => {
    onColorCommit?.(color);
  };

  const handleBorderScopeChange = (scope: BordersType) => {
    setLocalBorderScope(scope);
    onBorderScopeChange?.(scope);
  };

  const openColorPicker = () => {
    const modalId = 'TABLE_BORDER_COLOR_PICKER_MODAL';
    const closeColorPickerModal = () => modalService.closeModal(modalId);

    modalService.togglePluginPanel({
      id: modalId,
      Component: NewColorPicker,
      componentProps: {
        title: t('TablePlugin_Toolbar_BorderColorPicker_Title'),
        themeColors,
        customColors,
        currentColor,
        closeModal: closeColorPickerModal,
        onColorSelected: handleColorCommit,
        onColorPreview: handleColorPreview,
        onColorPreviewEnd,
        onColorAdded: (newColor: string) => {
          handleColorAdded(newColor, colorManager);
          handleColorCommit(newColor);
        },
        onColorDeleted: (color: string) => {
          handleColorDeleted(color, colorManager);
        },
        onResetColor: () => handleColorCommit(undefined),
        referenceElement: colorPickerRef.current,
        logBi,
        allowTransparent: true,
      },
      isMobile,
      positioning: {
        referenceElement: colorPickerRef.current,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: colorPickerRef.current ?? undefined,
    });
  };

  const isColorPickerOpen = () => modalService.isModalOpen('TABLE_BORDER_COLOR_PICKER_MODAL');

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;
      if (referenceElement?.contains(target as Node)) {
        return;
      }
      if (target?.closest('[role="tooltip"]')) {
        return;
      }
      closeModal();
    },
    disable: isColorPickerOpen(),
  });

  return (
    <Panel
      dataHook={TABLE_BORDER_MODAL}
      closeButtonProps={{ onClick: closeModal }}
      width={isMobile ? '100%' : 288}
      maxHeight={isMobile ? undefined : 555}
      height="fit-content"
    >
      <PanelHeader title={t('TablePlugin_Toolbar_BorderPanel_Title')} />
      <Box direction="vertical" overflow="auto">
        {onBorderScopeChange && (
          <>
            <BorderScopeSelector
              selectedScope={localBorderScope}
              onScopeChange={handleBorderScopeChange}
              canInnerHorizontal={canInnerHorizontal}
              canInnerVertical={canInnerVertical}
            />
            <Divider />
          </>
        )}
        <Box direction="vertical" padding="SP4" paddingTop="SP2" paddingBottom="SP3" gap="SP2">
          {isMixedColor || !canTransformToHex(currentColor) ? (
            <FieldSet
              legend={t('TablePlugin_Toolbar_BorderColor_Label')}
              legendPlacement="left"
              columns="1fr 30px"
              gap="small"
              alignment="center"
              dataHook={TABLE_BORDER_COLOR_INPUT}
            >
              <div />
              <Box height={30} width={30}>
                <FillPreview
                  fill={isMixedColor ? displayedAllCurrentColors : displayedCurrentColor}
                  onClick={openColorPicker}
                  ref={colorPickerRef}
                  dataHook={TABLE_BORDER_COLOR_PICKER}
                />
              </Box>
            </FieldSet>
          ) : (
            <ColorWithOpacityInput
              label={t('TablePlugin_Toolbar_BorderColor_Label')}
              fill={{
                type: 'color',
                color: currentColor,
                onChange: handleColorPreview,
                onChangeCommit: handleColorCommit,
                allowTransparent: true,
              }}
              onColorPress={openColorPicker}
              colorPickerRef={colorPickerRef}
              inputDataHook={TABLE_BORDER_COLOR_INPUT}
              fillPreviewDataHook={TABLE_BORDER_COLOR_PICKER}
              zIndex={zIndex}
              logBi={logBi}
            />
          )}
          {onBorderWidthPreview && onBorderWidthCommit && (
            <NumberInputWithLabel
              label={t('TablePlugin_Toolbar_BorderWidth_Label')}
              dataHook={TABLE_BORDER_WIDTH_INPUT}
              suffix={<Input.Affix>px</Input.Affix>}
              value={currentWidth}
              min={1}
              max={10}
              commitUnchanged
              onChange={handleBorderWidthPreview}
              onChangeCommit={handleBorderWidthCommit}
              logBi={logBi}
              zIndex={zIndex}
            />
          )}
        </Box>
      </Box>
    </Panel>
  );
};
