import { Box, FieldSet, FormField, Input, ToggleButton } from '@wix/design-system';
import {
  IndividualPaddingsSmall,
  MoveSmall,
  PaddingBottomSmall,
  PaddingHorizontalSmall,
  PaddingLeftSmall,
  PaddingRightSmall,
  PaddingTopSmall,
  PaddingVerticalSmall,
} from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useCallback, useContext, useEffect, useState } from 'react';

import { ModalServiceContext, RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import {
  InputWithSlider,
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { TABLE_BUTTONS_MODALS_ID } from '../consts.js';
import {
  TABLE_CELL_PADDING_BOTTOM,
  TABLE_CELL_PADDING_HORIZONTAL,
  TABLE_CELL_PADDING_LEFT,
  TABLE_CELL_PADDING_RIGHT,
  TABLE_CELL_PADDING_TOGGLE_INDIVIDUAL,
  TABLE_CELL_PADDING_TOP,
  TABLE_CELL_PADDING_VERTICAL,
  TABLE_CELL_SPACING_INPUT,
} from '../data-hooks.js';
import { TABLE_DEFAULTS } from '../defaults.js';

export type TableSpacingModalProps = {
  nodeId: string;
  referenceElement: HTMLElement | undefined;
  cellSpacing?: number;
  onCellSpacingPreview?: (spacing: number) => void;
  onCellSpacingCommit?: (spacing: number) => void;
  cellPadding?: number | number[];
  onCellPaddingPreview?: (padding: number | number[]) => void;
  onCellPaddingCommit?: (padding: number | number[]) => void;
};

export const TableSpacingModal: FC<TableSpacingModalProps> = ({
  nodeId,
  referenceElement,
  cellSpacing = TABLE_DEFAULTS.cellSpacing,
  onCellSpacingPreview,
  onCellSpacingCommit,
  cellPadding = [...TABLE_DEFAULTS.cellPadding],
  onCellPaddingPreview,
  onCellPaddingCommit,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');

  const logBi = useBiNext({
    modalId: TABLE_BUTTONS_MODALS_ID.SPACING,
    pluginId: 'table',
    nodeId,
  });

  const [localCellSpacing, setLocalCellSpacing] = useState(cellSpacing);

  // Normalize cellPadding to array format
  const normalizedPadding = Array.isArray(cellPadding)
    ? cellPadding
    : [cellPadding, cellPadding, cellPadding, cellPadding];
  const [localCellPadding, setLocalCellPadding] = useState(normalizedPadding);

  const containerEl = usePanelContainerElement();

  // Update local state when props change
  useEffect(() => {
    setLocalCellSpacing(cellSpacing);
  }, [cellSpacing]);

  useEffect(() => {
    const normalized = Array.isArray(cellPadding)
      ? cellPadding
      : [cellPadding, cellPadding, cellPadding, cellPadding];
    setLocalCellPadding(normalized);
  }, [cellPadding]);

  const closeModal = useCallback(() => {
    modalService.closeModal(TABLE_BUTTONS_MODALS_ID.SPACING);
  }, [modalService]);

  const handleCellSpacingPreview = useCallback(
    (spacing: number) => {
      setLocalCellSpacing(spacing);
      onCellSpacingPreview?.(spacing);
    },
    [onCellSpacingPreview]
  );

  const handleCellSpacingCommit = useCallback(
    (spacing: number) => {
      setLocalCellSpacing(spacing);
      onCellSpacingCommit?.(spacing);
    },
    [onCellSpacingCommit]
  );

  const handleCellPaddingPreview = useCallback(
    (padding: number[]) => {
      setLocalCellPadding(padding);
      onCellPaddingPreview?.(padding);
    },
    [onCellPaddingPreview]
  );

  const handleCellPaddingCommit = useCallback(
    (padding: number[]) => {
      setLocalCellPadding(padding);
      onCellPaddingCommit?.(padding);
    },
    [onCellPaddingCommit]
  );

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;
      if (referenceElement?.contains(target as Node)) {
        return;
      }
      if (target?.closest('[role="tooltip"]')) {
        return;
      }

      closeModal();
    },
    disable: false,
  });

  return (
    <Panel
      closeButtonProps={{ onClick: closeModal }}
      width={isMobile ? '100%' : 288}
      maxHeight={isMobile ? undefined : 555}
      height="fit-content"
    >
      <PanelHeader title={t('TablePlugin_Toolbar_SpacingModal_Title')} />
      <Box direction="vertical" overflow="auto">
        <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP3">
          <FormField inputWidth="100%">
            <FieldSet
              alignment="center"
              legend={t('TablePlugin_Toolbar_CellSpacing_Label')}
              infoContent={t('TablePlugin_Toolbar_CellSpacing_Info')}
            >
              <Box direction="horizontal" paddingRight="SP1" width="50%">
                <InputWithSlider
                  value={localCellSpacing}
                  dataHook={TABLE_CELL_SPACING_INPUT}
                  onChange={value => {
                    handleCellSpacingPreview(value);
                    logBi({ dataHook: TABLE_CELL_SPACING_INPUT, value });
                  }}
                  onChangeCommit={(value, originalValue) => {
                    if (value !== originalValue) {
                      handleCellSpacingCommit(value);
                    }
                  }}
                  zIndex={zIndex}
                  prefix={
                    <Input.Affix>
                      <MoveSmall />
                    </Input.Affix>
                  }
                  suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                  min={0}
                  max={20}
                />
              </Box>
            </FieldSet>
          </FormField>

          <PaddingFieldWithLabel
            logBi={logBi}
            label={t('TablePlugin_Toolbar_CellPadding_Label')}
            infoContent={t('TablePlugin_Toolbar_CellPadding_Info')}
            padding={localCellPadding}
            onPreview={handleCellPaddingPreview}
            onCommit={handleCellPaddingCommit}
            zIndex={zIndex}
          />
        </Box>
      </Box>
    </Panel>
  );
};

type PaddingFieldWithLabelProps = {
  logBi: ReturnType<typeof useBiNext>;
  label: string;
  infoContent: string;
  padding: number[];
  onPreview: (padding: number[]) => void;
  onCommit: (padding: number[]) => void;
  zIndex: string | number;
};

const PaddingFieldWithLabel: React.FC<PaddingFieldWithLabelProps> = ({
  logBi,
  label,
  infoContent,
  padding,
  onPreview,
  onCommit,
  zIndex,
}) => {
  const { t } = useContext(RicosContext);
  const containerEl = usePanelContainerElement();

  const paddingTop = padding[0];
  const paddingRight = padding[1];
  const paddingBottom = padding[2];
  const paddingLeft = padding[3];

  const [mode, setMode] = useState<'individual' | 'directional'>(() => {
    if (paddingLeft === paddingRight && paddingTop === paddingBottom) {
      return 'directional';
    }
    return 'individual';
  });

  const createPaddingSliderHandlers = (
    getNextPadding: (value: number) => number[],
    dataHook: string
  ) => ({
    onChange: (value: number) => {
      onPreview(getNextPadding(value));
      logBi({ dataHook, value });
    },
    onChangeCommit: (value: number, originalValue: number) => {
      if (value !== originalValue) {
        onCommit(getNextPadding(value));
      }
    },
  });

  return (
    <Box direction="vertical">
      <FormField inputWidth="100%">
        <FieldSet
          alignment="center"
          legend={label}
          infoContent={infoContent}
          suffix={
            <Box width="24px" height="24px" align="center" verticalAlign="middle">
              <ToggleButton
                border
                labelValue={t('TablePlugin_Toolbar_CellPadding_ToggleIndividual_Label')}
                size="tiny"
                tooltipProps={{ appendTo: containerEl, zIndex }}
                selected={mode === 'individual'}
                onClick={() => {
                  setMode(() => (mode === 'individual' ? 'directional' : 'individual'));
                  logBi({
                    dataHook: TABLE_CELL_PADDING_TOGGLE_INDIVIDUAL,
                    value: mode === 'individual' ? 'directional' : 'individual',
                  });
                  if (mode === 'individual') {
                    onCommit([paddingTop, paddingLeft, paddingTop, paddingLeft]);
                  }
                }}
                dataHook={TABLE_CELL_PADDING_TOGGLE_INDIVIDUAL}
              >
                <IndividualPaddingsSmall />
              </ToggleButton>
            </Box>
          }
        >
          {(() => {
            switch (mode) {
              case 'individual':
                return (
                  <Box direction="vertical" gap="SP1">
                    <Box direction="horizontal" gap="SP2">
                      <InputWithSlider
                        value={paddingLeft}
                        {...createPaddingSliderHandlers(
                          value => [paddingTop, paddingRight, paddingBottom, value],
                          TABLE_CELL_PADDING_LEFT
                        )}
                        dataHook={TABLE_CELL_PADDING_LEFT}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingLeftSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                      <InputWithSlider
                        value={paddingTop}
                        {...createPaddingSliderHandlers(
                          value => [value, paddingRight, paddingBottom, paddingLeft],
                          TABLE_CELL_PADDING_TOP
                        )}
                        dataHook={TABLE_CELL_PADDING_TOP}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingTopSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                    </Box>
                    <Box direction="horizontal" gap="SP2">
                      <InputWithSlider
                        value={paddingRight}
                        {...createPaddingSliderHandlers(
                          value => [paddingTop, value, paddingBottom, paddingLeft],
                          TABLE_CELL_PADDING_RIGHT
                        )}
                        dataHook={TABLE_CELL_PADDING_RIGHT}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingRightSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                      <InputWithSlider
                        value={paddingBottom}
                        {...createPaddingSliderHandlers(
                          value => [paddingTop, paddingRight, value, paddingLeft],
                          TABLE_CELL_PADDING_BOTTOM
                        )}
                        dataHook={TABLE_CELL_PADDING_BOTTOM}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingBottomSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                    </Box>
                  </Box>
                );
              case 'directional':
                return (
                  <Box direction="horizontal" gap="SP2">
                    <InputWithSlider
                      value={paddingLeft}
                      {...createPaddingSliderHandlers(
                        value => [paddingTop, value, paddingTop, value],
                        TABLE_CELL_PADDING_HORIZONTAL
                      )}
                      dataHook={TABLE_CELL_PADDING_HORIZONTAL}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingHorizontalSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={100}
                    />
                    <InputWithSlider
                      value={paddingTop}
                      {...createPaddingSliderHandlers(
                        value => [value, paddingRight, value, paddingRight],
                        TABLE_CELL_PADDING_VERTICAL
                      )}
                      dataHook={TABLE_CELL_PADDING_VERTICAL}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingVerticalSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={100}
                    />
                  </Box>
                );
              default:
                return null;
            }
          })()}
        </FieldSet>
      </FormField>
    </Box>
  );
};
