import { Box, Button, SidePanel, Text } from '@wix/design-system';
import { StatusAlertFilledSmall } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import type { FC } from 'react';
import React, { useCallback, useContext, useEffect, useRef, useState } from 'react';

import { EditorContext, ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import { CELL_AUTO_MIN_WIDTH, ROW_DEFAULT_HEIGHT } from '../consts.js';
import {
  INSERT_TABLE_MODAL,
  INSERT_TABLE_MODAL_ADD_BUTTON,
  INSERT_TABLE_MODAL_COLUMNS_INPUT,
  INSERT_TABLE_MODAL_ERROR_MESSAGE,
  INSERT_TABLE_MODAL_FOOTER_ACTIONS,
  INSERT_TABLE_MODAL_GRID_SELECTOR,
  INSERT_TABLE_MODAL_ROWS_INPUT,
  ROOT,
} from '../data-hooks.js';
import styles from '../statics/styles/table-settings-modal-scss.js';
import { getDefaultsSettings, isCellsNumberInvalid } from '../table-util.js';
import { getDefaultTable } from '../tiptap/defaults.js';
import { TableSettingsCountSection } from '../toolbar/table-settings-count-section.js';
import { INSERT_TABLE_MODAL_ID, TABLE_TYPE } from '../types.js';
import { TableGridSelector } from './table-grid-selector.js';

export const InsertModal: FC = () => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const { getPublicCommands } = useContext(EditorContext);

  const [rowCount, setRowCount] = useState(4);
  const [colCount, setColCount] = useState(4);
  const [submittedInvalidCol, setSubmittedInvalidCol] = useState<boolean>();
  const [submittedInvalidRow, setSubmittedInvalidRow] = useState<boolean>();
  const [invalidCellNum, setInvalidCellNum] = useState<boolean>();
  const [isTyping, setIsTyping] = useState(false);

  const colsInput = useRef<HTMLInputElement | null>(null);
  const rowsInput = useRef<HTMLInputElement | null>(null);

  const logBi = useBiNext({ pluginId: 'table', modalId: INSERT_TABLE_MODAL_ID });

  useEffect(() => {
    if (isTyping) {
      const timer = setTimeout(() => {
        validateCounts();
        setIsTyping(false);
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [colCount, rowCount, isTyping]);

  const validateCounts = () => {
    const invalidCol = colCount < 1;
    const invalidRow = rowCount < 1;
    const invalidCells = isCellsNumberInvalid(rowCount, colCount);

    setSubmittedInvalidCol(invalidCol);
    setSubmittedInvalidRow(invalidRow);
    setInvalidCellNum(invalidCells);

    return invalidCol || invalidRow || invalidCells;
  };

  const onCreateTableClicked = () => {
    const hasError = validateCounts();

    if (hasError) {
      if (submittedInvalidCol || invalidCellNum) {
        colsInput.current?.focus();
      } else {
        rowsInput.current?.focus();
      }
    } else {
      const { config } = getDefaultsSettings(rowCount, colCount);
      onTableAdd({ config });
    }
  };

  const onColCountChange = (newColCount: number) => {
    setColCount(newColCount);
    setIsTyping(true);
  };

  const onRowCountChange = (newRowCount: number) => {
    setRowCount(newRowCount);
    setIsTyping(true);
  };

  const onGridSelectionChange = useCallback((cols: number, rows: number) => {
    setColCount(cols);
    setRowCount(rows);
    setSubmittedInvalidCol(false);
    setSubmittedInvalidRow(false);
    setInvalidCellNum(false);
  }, []);

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Enter') {
      onCreateTableClicked();
    }
  };

  const hasError = submittedInvalidCol || submittedInvalidRow || invalidCellNum;

  const closeModal = () => modalService.closeModal(INSERT_TABLE_MODAL_ID);

  const onTableAdd = (table: $TSFixMe) => {
    const rowNum = table.config.rowsHeight.length;
    const colNum = table.config.colsWidth.length;
    getPublicCommands().insertBlockWithBlankLines(TABLE_TYPE, {
      dimensions: {
        rowsHeight: Array(rowNum).fill(ROW_DEFAULT_HEIGHT),
        colsMinWidth: Array(colNum).fill(CELL_AUTO_MIN_WIDTH),
      },
      content: getDefaultTable(rowNum, colNum),
    });
    closeModal();
  };

  return (
    <Panel
      closeButtonProps={{ onClick: closeModal }}
      dataHook={classNames(ROOT, INSERT_TABLE_MODAL)}
      height="fit-content"
    >
      <PanelHeader title={t('TablePlugin_SettingsModal_Title')} />

      <Box direction="vertical" padding="SP4 SP5" gap="SP4">
        <Box direction="horizontal" gap="SP3" className={styles.pickerField}>
          <TableSettingsCountSection
            title={t('TablePlugin_SettingsModal_ColCount')}
            input={colCount}
            onCountChange={onColCountChange}
            onBlur={validateCounts}
            dataHook={INSERT_TABLE_MODAL_COLUMNS_INPUT}
            hasError={submittedInvalidCol || invalidCellNum}
            inputRef={colsInput}
            onKeyDown={onKeyDown}
            logBi={logBi}
          />
          <TableSettingsCountSection
            title={t('TablePlugin_SettingsModal_RowCount')}
            input={rowCount}
            onCountChange={onRowCountChange}
            onBlur={validateCounts}
            dataHook={INSERT_TABLE_MODAL_ROWS_INPUT}
            hasError={submittedInvalidRow || invalidCellNum}
            inputRef={rowsInput}
            onKeyDown={onKeyDown}
            logBi={logBi}
          />
        </Box>

        <TableGridSelector
          colCount={colCount}
          rowCount={rowCount}
          onSelectionChange={onGridSelectionChange}
          dataHook={INSERT_TABLE_MODAL_GRID_SELECTOR}
        />

        {hasError && (
          <Box direction="horizontal" gap="9px" verticalAlign="middle">
            <Box color="R10">
              <StatusAlertFilledSmall />
            </Box>
            <Text size="small" skin="error" dataHook={INSERT_TABLE_MODAL_ERROR_MESSAGE}>
              {invalidCellNum
                ? t('TablePlugin_SettingsModal_limitError')
                : t('TablePlugin_SettingsModal_ErrorMessage')}
            </Text>
          </Box>
        )}
      </Box>

      <SidePanel.Footer showDivider>
        <Box align="right" dataHook={INSERT_TABLE_MODAL_FOOTER_ACTIONS}>
          <Button
            onClick={() => {
              logBi({ dataHook: INSERT_TABLE_MODAL_FOOTER_ACTIONS });
              onCreateTableClicked();
            }}
            priority="primary"
            size="small"
            dataHook={INSERT_TABLE_MODAL_ADD_BUTTON}
          >
            {t('TablePlugin_SettingsModal_CreateTable_Button')}
          </Button>
        </Box>
      </SidePanel.Footer>
    </Panel>
  );
};
