import classNames from 'classnames';
import type { FC } from 'react';
import React, { useCallback, useState } from 'react';

import styles from './table-grid-selector-scss.js';

const MAX_COLS = 8;
const MAX_ROWS = 6;

type TableGridSelectorProps = {
  colCount: number;
  rowCount: number;
  onSelectionChange: (cols: number, rows: number) => void;
  dataHook?: string;
};

type HoverCell = { col: number; row: number } | null;

export const TableGridSelector: FC<TableGridSelectorProps> = ({
  colCount,
  rowCount,
  onSelectionChange,
  dataHook,
}) => {
  const [hoverCell, setHoverCell] = useState<HoverCell>(null);

  const isHovering = hoverCell !== null;
  const effectiveCol = hoverCell?.col ?? Math.min(colCount, MAX_COLS);
  const effectiveRow = hoverCell?.row ?? Math.min(rowCount, MAX_ROWS);

  const getCellFromEvent = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    const target = e.target as HTMLElement;
    const col = target.dataset.col;
    const row = target.dataset.row;
    if (col && row) {
      return { col: Number(col), row: Number(row) };
    }
    return null;
  }, []);

  const handleMouseOver = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const cell = getCellFromEvent(e);
      if (cell) {
        setHoverCell(prev => (prev?.col === cell.col && prev.row === cell.row ? prev : cell));
      }
    },
    [getCellFromEvent]
  );

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const cell = getCellFromEvent(e);
      if (cell) {
        onSelectionChange(cell.col, cell.row);
      }
    },
    [getCellFromEvent, onSelectionChange]
  );

  const handleMouseLeave = useCallback(() => {
    setHoverCell(null);
  }, []);

  const renderCells = () => {
    const cells: React.ReactNode[] = [];
    const lockedCol = Math.min(colCount, MAX_COLS);
    const lockedRow = Math.min(rowCount, MAX_ROWS);

    for (let row = 1; row <= MAX_ROWS; row++) {
      for (let col = 1; col <= MAX_COLS; col++) {
        const isInHoverArea = col <= effectiveCol && row <= effectiveRow;
        const isLocked = col <= lockedCol && row <= lockedRow;
        const isHoverPreview = isInHoverArea && !isLocked;

        // When not hovering: all locked cells show visible border
        // When hovering: only locked cells in hover area show visible border
        const showLockedWithBorder = isLocked && (!isHovering || isInHoverArea);
        const showLockedHidden = isLocked && isHovering && !isInHoverArea;

        cells.push(
          <div
            key={`${col}-${row}`}
            data-col={col}
            data-row={row}
            className={classNames(styles.cell, {
              [styles.locked]: showLockedWithBorder,
              [styles.lockedHidden]: showLockedHidden,
              [styles.hoverPreview]: isHoverPreview,
            })}
            role="presentation"
          />
        );
      }
    }

    return cells;
  };

  return (
    <div
      data-hook={dataHook}
      className={styles.gridContainer}
      onMouseOver={handleMouseOver}
      onMouseLeave={handleMouseLeave}
      onClick={handleClick}
      aria-hidden="true"
      tabIndex={-1}
    >
      {renderCells()}
    </div>
  );
};
